1	const path = require('node:path');
2	const fs = require('node:fs');
3	const crypto = require('node:crypto');
4	const express = require('express');
5	const multer = require('multer');
6	
7	const config = require('./config');
8	const db = require('./db');
9	const { hashSenha, confereSenha } = require('./senha');
10	const pontos = require('./pontos');
11	const banca = require('./banca');
12	const feed = require('./feed');
13	const v = require('./views');
14	
15	const PASTA_UPLOADS = path.join(config.PASTA_DADOS, 'uploads');
16	fs.mkdirSync(PASTA_UPLOADS, { recursive: true });
17	
18	const COOKIE = 'maxx_sessao';
19	const DURACAO_SESSAO_MS = 30 * 24 * 60 * 60 * 1000;
20	const POSTS_POR_PAGINA = 20;
21	
22	// Erro com mensagem que pode ser mostrada ao usuário.
23	class ErroUsuario extends Error {
24	  constructor(mensagem, status = 400) {
25	    super(mensagem);
26	    this.status = status;
27	  }
28	}
29	
30	// ---------- Upload de imagens ----------
31	const TIPOS_IMAGEM = { 'image/jpeg': '.jpg', 'image/png': '.png', 'image/webp': '.webp', 'image/gif': '.gif' };
32	const upload = multer({
33	  storage: multer.diskStorage({
34	    destination: PASTA_UPLOADS,
35	    filename: (req, file, cb) => cb(null, crypto.randomBytes(16).toString('hex') + TIPOS_IMAGEM[file.mimetype]),
36	  }),
37	  limits: { fileSize: config.TAMANHO_MAX_IMAGEM_MB * 1024 * 1024, files: 1 },
38	  fileFilter: (req, file, cb) => {
39	    if (TIPOS_IMAGEM[file.mimetype]) cb(null, true);
40	    else cb(new ErroUsuario('Formato de imagem não suportado. Use JPG, PNG, WEBP ou GIF.'));
41	  },
42	});
43	
44	function apagarArquivo(nome) {
45	  if (nome) fs.rm(path.join(PASTA_UPLOADS, path.basename(nome)), { force: true }, () => {});
46	}
47	
48	// ---------- Sessão ----------
49	const hashToken = (t) => crypto.createHash('sha256').update(t).digest('hex');
50	
51	function lerCookie(req, nome) {
52	  for (const parte of (req.headers.cookie || '').split(';')) {
53	    const [k, ...resto] = parte.trim().split('=');
54	    if (k === nome) return decodeURIComponent(resto.join('='));
55	  }
56	  return null;
57	}
58	
59	function iniciarSessao(res, usuarioId) {
60	  const token = crypto.randomBytes(32).toString('hex');
61	  db.prepare('INSERT INTO sessoes (token_hash, usuario_id, expira_em) VALUES (?, ?, ?)').run(
62	    hashToken(token),
63	    usuarioId,
64	    Date.now() + DURACAO_SESSAO_MS,
65	  );
66	  res.cookie(COOKIE, token, {
67	    httpOnly: true,
68	    sameSite: 'lax',
69	    secure: process.env.NODE_ENV === 'production',
70	    maxAge: DURACAO_SESSAO_MS,
71	  });
72	}
73	
74	// ---------- Helpers ----------
75	// Quantos avisos do mural a pessoa ainda não viu (os que ela mesma publicou não contam).
76	function avisosNovos(usuario) {
77	  if (!usuario) return 0;
78	  return db
79	    .prepare('SELECT COUNT(*) AS n FROM avisos WHERE id > ? AND (autor_id IS NULL OR autor_id != ?)')
80	    .get(usuario.mural_visto_id, usuario.id).n;
81	}
82	
83	function enviar(req, res, { titulo, ativo, conteudo, status = 200 }) {
84	  const novos = avisosNovos(req.usuario);
85	  res.status(status).type('html').send(String(v.layout({ usuario: req.usuario, titulo, ativo, conteudo, avisosNovos: novos })));
86	}
87	
88	function exigeLogin(req, res, next) {
89	  if (!req.usuario) return res.redirect('/entrar');
90	  next();
91	}
92	
93	const exigePapel = (...papeis) => (req, res, next) => {
94	  if (!papeis.includes(req.usuario?.papel)) throw new ErroUsuario('Você não tem permissão para fazer isso.', 403);
95	  next();
96	};
97	
98	// Só aceita caminhos internos para evitar redirecionar para outro site.
99	const caminhoSeguro = (p, padrao = '/') => (typeof p === 'string' && /^\/(?!\/)/.test(p) && !p.includes('\\') ? p : padrao);
100	
101	const texto = (valor, max) => String(valor ?? '').trim().slice(0, max);
102	const idParam = (req) => {
103	  const id = Number(req.params.id);
104	  if (!Number.isInteger(id) || id <= 0) throw new ErroUsuario('Página não encontrada.', 404);
105	  return id;
106	};
107	
108	const { SQL_POST } = feed;
109	
110	// ---------- App ----------
111	const app = express();
112	app.disable('x-powered-by');
113	// Usa o IP real do visitante quando o app roda atrás de um proxy (para o limite de tentativas
114	// do código da banca não juntar todo mundo num IP só). No Azure App Service há sempre um
115	// proxy da Microsoft na frente; nos outros casos, só confia em proxy na mesma máquina.
116	app.set('trust proxy', process.env.WEBSITE_SITE_NAME ? 1 : 'loopback');
117	// O proxy do Azure manda o IP com a porta ("1.2.3.4:5678"); a porta muda a cada conexão.
118	const ipVisitante = (req) => String(req.ip || '').replace(/^\[(.+)\]:\d+$/, '$1').replace(/^(\d+\.\d+\.\d+\.\d+):\d+$/, '$1');
119	app.use(express.urlencoded({ extended: false, limit: '100kb' }));
120	app.use(express.static(path.join(__dirname, '..', 'public')));
121	
122	app.use((req, res, next) => {
123	  res.set('X-Content-Type-Options', 'nosniff');
124	  res.set('X-Frame-Options', 'DENY');
125	  res.set('Referrer-Policy', 'same-origin');
126	  const token = lerCookie(req, COOKIE);
127	  if (token) {
128	    req.usuario = db
129	      .prepare('SELECT u.* FROM sessoes s JOIN usuarios u ON u.id = s.usuario_id WHERE s.token_hash = ? AND s.expira_em > ?')
130	      .get(hashToken(token), Date.now());
131	    // Contas da banca só valem enquanto o acesso da banca estiver ligado.
132	    if (req.usuario && !banca.ligada() && banca.ehContaBanca(req.usuario.email)) req.usuario = undefined;
133	  }
134	  next();
135	});
136	
137	// ----- Entrar / cadastrar / sair -----
138	app.get('/entrar', (req, res) => {
139	  if (req.usuario) return res.redirect('/');
140	  enviar(req, res, { titulo: 'Entrar', conteudo: v.telaEntrar({ banca: banca.ligada() }) });
141	});
142	
143	app.post('/entrar', (req, res) => {
144	  const email = texto(req.body.email, 200).toLowerCase();
145	  const usuario = db.prepare('SELECT * FROM usuarios WHERE email = ?').get(email);
146	  if (!usuario || !confereSenha(String(req.body.senha || ''), usuario.senha_hash)) {
147	    return enviar(req, res, { titulo: 'Entrar', status: 401, conteudo: v.telaEntrar({ erro: 'E-mail ou senha incorretos.', email, banca: banca.ligada() }) });
148	  }
149	  iniciarSessao(res, usuario.id);
150	  res.redirect('/');
151	});
152	
153	app.get('/cadastrar', (req, res) => {
154	  if (req.usuario) return res.redirect('/');
155	  enviar(req, res, { titulo: 'Cadastrar', conteudo: v.telaCadastrar({}) });
156	});
157	
158	app.post('/cadastrar', (req, res) => {
159	  const dados = {
160	    nome: texto(req.body.nome, 60),
161	    email: texto(req.body.email, 200).toLowerCase(),
162	    curso: texto(req.body.curso, 100),
163	  };
164	  const senha = String(req.body.senha || '');
165	  const dominio = dados.email.split('@')[1];
166	  let erro = null;
167	  if (dados.nome.length < 2) erro = 'Informe seu nome.';
168	  else if (!/^[^\s@]+@[^\s@]+$/.test(dados.email) || !config.DOMINIOS_PERMITIDOS.includes(dominio))
169	    erro = `Use seu e-mail da faculdade (@${config.DOMINIOS_PERMITIDOS.join(', @')}).`;
170	  else if (!config.CURSOS.includes(dados.curso)) erro = 'Selecione seu curso.';
171	  else if (senha.length < 8) erro = 'A senha precisa ter pelo menos 8 caracteres.';
172	  else if (banca.ehContaBanca(dados.email) || db.prepare('SELECT 1 FROM usuarios WHERE email = ?').get(dados.email)) erro = 'Já existe uma conta com esse e-mail.';
173	  if (erro) return enviar(req, res, { titulo: 'Cadastrar', status: 400, conteudo: v.telaCadastrar({ erro, dados }) });
174	
175	  const { lastInsertRowid } = db
176	    .prepare('INSERT INTO usuarios (nome, email, senha_hash, curso, papel) VALUES (?, ?, ?, ?, ?)')
177	    .run(dados.nome, dados.email, hashSenha(senha), dados.curso, config.DOMINIOS_PROFESSORES.includes(dominio) ? 'professor' : 'aluno');
178	  iniciarSessao(res, Number(lastInsertRowid));
179	  res.redirect('/');
180	});
181	
182	app.post('/banca', (req, res) => {
183	  if (!banca.ligada()) return res.redirect('/entrar');
184	  const r = banca.entrar({ codigo: texto(req.body.codigo, 200), perfil: String(req.body.perfil || ''), ip: ipVisitante(req) });
185	  if (r.erro) {
186	    return enviar(req, res, { titulo: 'Entrar', status: 401, conteudo: v.telaEntrar({ banca: true, erroBanca: r.erro }) });
187	  }
188	  iniciarSessao(res, r.usuarioId);
189	  res.redirect('/');
190	});
191	
192	app.post('/sair', (req, res) => {
193	  const token = lerCookie(req, COOKIE);
194	  if (token) db.prepare('DELETE FROM sessoes WHERE token_hash = ?').run(hashToken(token));
195	  res.clearCookie(COOKIE);
196	  res.redirect('/entrar');
197	});
198	
199	// Tudo daqui pra baixo exige login.
200	app.use(exigeLogin);
201	app.use('/uploads', express.static(PASTA_UPLOADS, { maxAge: '7d' }));
202	
203	// ----- Feed -----
204	app.get('/', (req, res) => {
205	  const pagina = Math.max(1, parseInt(req.query.pagina, 10) || 1);
206	  const { itens, temMais } = feed.pagina({ usuarioId: req.usuario.id, pagina, porPagina: POSTS_POR_PAGINA });
207	  const avisoFixado = db.prepare('SELECT * FROM avisos WHERE fixado = 1 ORDER BY id DESC LIMIT 1').get();
208	  enviar(req, res, {
209	    ativo: 'inicio',
210	    conteudo: v.feed({ itens, avisoFixado, pagina, temMais }),
211	  });
212	});
213	
214	// ----- Posts -----
215	app.get('/novo', (req, res) => enviar(req, res, { titulo: 'Novo post', ativo: 'novo', conteudo: v.novoPost({}) }));
216	
217	app.post('/posts', upload.single('imagem'), (req, res) => {
218	  const legenda = texto(req.body.legenda, 2200);
219	  const imagem = req.file?.filename || null;
220	  if (!imagem && !legenda) {
221	    return enviar(req, res, { titulo: 'Novo post', ativo: 'novo', status: 400, conteudo: v.novoPost({ erro: 'Adicione uma foto ou escreva algo.' }) });
222	  }
223	  db.prepare('INSERT INTO posts (usuario_id, imagem, legenda) VALUES (?, ?, ?)').run(req.usuario.id, imagem, legenda);
224	  pontos.registrarConquistas(req.usuario.id);
225	  res.redirect('/');
226	});
227	
228	function buscarPost(req) {
229	  const post = db.prepare(`${SQL_POST} WHERE p.id = ?`).get(req.usuario.id, idParam(req));
230	  if (!post) throw new ErroUsuario('Esse post não existe mais.', 404);
231	  return post;
232	}
233	
234	app.get('/posts/:id', (req, res) => {
235	  const post = buscarPost(req);
236	  const comentarios = db
237	    .prepare(
238	      `SELECT c.*, u.nome, u.avatar, u.papel FROM comentarios c JOIN usuarios u ON u.id = c.usuario_id
239	       WHERE c.post_id = ? ORDER BY c.id`,
240	    )
241	    .all(post.id);
242	  enviar(req, res, { titulo: `Post de ${post.nome}`, conteudo: v.postDetalhe({ post, comentarios, usuario: req.usuario }) });
243	});
244	
245	app.post('/posts/:id/curtir', (req, res) => {
246	  const post = buscarPost(req);
247	  if (post.curti) db.prepare('DELETE FROM curtidas WHERE post_id = ? AND usuario_id = ?').run(post.id, req.usuario.id);
248	  else {
249	    db.prepare('INSERT OR IGNORE INTO curtidas (post_id, usuario_id) VALUES (?, ?)').run(post.id, req.usuario.id);
250	    pontos.registrarConquistas(post.usuario_id);
251	  }
252	  res.redirect(`${caminhoSeguro(req.body.voltar)}#post-${post.id}`);
253	});
254	
255	app.post('/posts/:id/comentar', (req, res) => {
256	  const post = buscarPost(req);
257	  const t = texto(req.body.texto, 500);
258	  if (t) {
259	    db.prepare('INSERT INTO comentarios (post_id, usuario_id, texto) VALUES (?, ?, ?)').run(post.id, req.usuario.id, t);
260	    pontos.registrarConquistas(req.usuario.id);
261	  }
262	  // Comentou pelo feed: volta para o mesmo post no feed. Senão, para a página do post.
263	  if (req.body.voltar) return res.redirect(`${caminhoSeguro(req.body.voltar)}#post-${post.id}`);
264	  res.redirect(`/posts/${post.id}#comentar`);
265	});
266	
267	app.post('/posts/:id/apagar', (req, res) => {
268	  const post = buscarPost(req);
269	  if (post.usuario_id !== req.usuario.id && req.usuario.papel !== 'admin') throw new ErroUsuario('Você não pode apagar este post.', 403);
270	  db.prepare('DELETE FROM posts WHERE id = ?').run(post.id);
271	  apagarArquivo(post.imagem);
272	  res.redirect(`/u/${post.usuario_id}`);
273	});
274	
275	app.post('/comentarios/:id/apagar', (req, res) => {
276	  const c = db.prepare('SELECT * FROM comentarios WHERE id = ?').get(idParam(req));
277	  if (!c) throw new ErroUsuario('Comentário não encontrado.', 404);
278	  if (c.usuario_id !== req.usuario.id && req.usuario.papel !== 'admin') throw new ErroUsuario('Você não pode apagar este comentário.', 403);
279	  db.prepare('DELETE FROM comentarios WHERE id = ?').run(c.id);
280	  res.redirect(`/posts/${c.post_id}`);
281	});
282	
283	// ----- Perfil -----
284	app.get('/u/:id', (req, res) => {
285	  const p = db.prepare('SELECT * FROM usuarios WHERE id = ?').get(idParam(req));
286	  if (!p) throw new ErroUsuario('Usuário não encontrado.', 404);
287	  const ehAluno = p.papel === 'aluno';
288	  enviar(req, res, {
289	    titulo: p.nome,
290	    ativo: p.id === req.usuario.id ? 'perfil' : '',
291	    conteudo: v.perfil({
292	      perfil: p,
293	      usuario: req.usuario,
294	      msg: req.query.ok === 'medalha' ? 'Medalha entregue! 🎉' : null,
295	      stats: ehAluno ? pontos.statsDoAluno(p.id) : null,
296	      medalhas: ehAluno
297	        ? db
298	            .prepare(
299	              `SELECT m.*, t.nome, t.emoji, t.pontos, pr.nome AS professor_nome FROM medalhas m
300	               JOIN tipos_medalha t ON t.id = m.tipo_id LEFT JOIN usuarios pr ON pr.id = m.professor_id
301	               WHERE m.aluno_id = ? ORDER BY m.id DESC`,
302	            )
303	            .all(p.id)
304	        : [],
305	      medalhasDadas: p.papel === 'professor' ? db.prepare('SELECT COUNT(*) AS n FROM medalhas WHERE professor_id = ?').get(p.id).n : 0,
306	      tiposMedalha: db.prepare('SELECT * FROM tipos_medalha ORDER BY pontos DESC').all(),
307	      posts: db.prepare('SELECT id, imagem, legenda FROM posts WHERE usuario_id = ? ORDER BY id DESC').all(p.id),
308	    }),
309	  });
310	});
311	
312	// Troféus: conquistas e medalhas do aluno, as que já ganhou e as que faltam.
313	app.get('/u/:id/trofeus', (req, res) => {
314	  const p = db.prepare("SELECT * FROM usuarios WHERE id = ? AND papel = 'aluno'").get(idParam(req));
315	  if (!p) throw new ErroUsuario('Só alunos ganham troféus.', 404);
316	  const datasConquistas = Object.fromEntries(
317	    db.prepare('SELECT conquista, criado_em FROM conquistas_alunos WHERE aluno_id = ?').all(p.id).map((c) => [c.conquista, c.criado_em]),
318	  );
319	  const medalhasPorTipo = db
320	    .prepare(
321	      `SELECT t.*, COUNT(m.id) AS vezes, MAX(m.criado_em) AS ultima_em
322	       FROM tipos_medalha t LEFT JOIN medalhas m ON m.tipo_id = t.id AND m.aluno_id = ?
323	       GROUP BY t.id ORDER BY t.pontos DESC, t.id`,
324	    )
325	    .all(p.id);
326	  enviar(req, res, {
327	    titulo: `Troféus de ${p.nome}`,
328	    ativo: p.id === req.usuario.id ? 'perfil' : '',
329	    conteudo: v.trofeus({ perfil: p, usuario: req.usuario, stats: pontos.statsDoAluno(p.id), datasConquistas, medalhasPorTipo }),
330	  });
331	});
332	
333	app.post('/u/:id/medalha', exigePapel('professor'), (req, res) => {
334	  const aluno = db.prepare("SELECT * FROM usuarios WHERE id = ? AND papel = 'aluno'").get(idParam(req));
335	  if (!aluno) throw new ErroUsuario('Medalhas só podem ser dadas para alunos.');
336	  const tipo = db.prepare('SELECT * FROM tipos_medalha WHERE id = ?').get(Number(req.body.tipo_id));
337	  if (!tipo) throw new ErroUsuario('Escolha uma medalha válida.');
338	  db.prepare('INSERT INTO medalhas (aluno_id, professor_id, tipo_id, mensagem) VALUES (?, ?, ?, ?)').run(
339	    aluno.id,
340	    req.usuario.id,
341	    tipo.id,
342	    texto(req.body.mensagem, 200),
343	  );
344	  pontos.registrarConquistas(aluno.id);
345	  res.redirect(`/u/${aluno.id}?ok=medalha`);
346	});
347	
348	app.get('/perfil/editar', (req, res) =>
349	  enviar(req, res, { titulo: 'Editar perfil', ativo: 'perfil', conteudo: v.editarPerfil({ usuario: req.usuario }) }),
350	);
351	
352	app.post('/perfil/editar', upload.single('avatar'), (req, res) => {
353	  const nome = texto(req.body.nome, 60);
354	  const bio = texto(req.body.bio, 300);
355	  let curso = req.usuario.curso;
356	  if (req.usuario.papel !== 'admin') curso = texto(req.body.curso, 100);
357	  let erro = null;
358	  if (nome.length < 2) erro = 'Informe seu nome.';
359	  else if (req.usuario.papel !== 'admin' && !config.CURSOS.includes(curso)) erro = 'Selecione um curso válido.';
360	  if (erro) {
361	    apagarArquivo(req.file?.filename);
362	    return enviar(req, res, { titulo: 'Editar perfil', ativo: 'perfil', status: 400, conteudo: v.editarPerfil({ usuario: req.usuario, erro }) });
363	  }
364	  const avatar = req.file ? req.file.filename : req.usuario.avatar;
365	  db.prepare('UPDATE usuarios SET nome = ?, bio = ?, curso = ?, avatar = ? WHERE id = ?').run(nome, bio, curso, avatar, req.usuario.id);
366	  if (req.file) apagarArquivo(req.usuario.avatar);
367	  res.redirect(`/u/${req.usuario.id}`);
368	});
369	
370	// ----- Ranking -----
371	app.get('/ranking', (req, res) => {
