388	const listarAvisos = () =>
389	  db
390	    .prepare(
391	      `SELECT a.*, a.autor_id AS usuario_id, u.nome, u.papel, u.avatar
392	       FROM avisos a LEFT JOIN usuarios u ON u.id = a.autor_id
393	       ORDER BY a.fixado DESC, a.id DESC`,
394	    )
