401	  const vistoAte = req.usuario.mural_visto_id;
402	  for (const a of avisos) {
403	    a.novo = a.id > vistoAte && a.autor_id !== req.usuario.id;
404	    a.podeApagar = podeApagarAviso(req.usuario, a);
405	  }
406	  // Abriu o mural: tudo o que está nele passa a contar como lido.
407	  const ultimo = Math.max(vistoAte, ...avisos.map((a) => a.id));
408	  if (ultimo > vistoAte) {
409	    db.prepare('UPDATE usuarios SET mural_visto_id = ? WHERE id = ?').run(ultimo, req.usuario.id);
410	    req.usuario.mural_visto_id = ultimo;
411	  }
412	  enviar(req, res, { titulo: 'Mural', ativo: 'mural', status, conteudo: v.mural({ avisos, usuario: req.usuario, erro }) });
413	}
414	
