420	  if (!titulo || !t) return telaMural(req, res, { erro: 'Preencha o título e o aviso.', status: 400 });
421	  const fixado = req.usuario.papel === 'admin' && req.body.fixado ? 1 : 0;
422	  const { lastInsertRowid } = db
423	    .prepare('INSERT INTO avisos (autor_id, titulo, texto, fixado) VALUES (?, ?, ?, ?)')
424	    .run(req.usuario.id, titulo, t, fixado);
