435	  if (!aviso) throw new ErroUsuario('Esse aviso não existe mais.', 404);
436	  if (!podeApagarAviso(req.usuario, aviso)) throw new ErroUsuario('Você só pode apagar os avisos que você publicou.', 403);
437	  db.prepare('DELETE FROM avisos WHERE id = ?').run(aviso.id);
