455	  const id = idParam(req);
456	  const papel = req.body.papel;
457	  if (!['aluno', 'professor', 'admin'].includes(papel)) throw new ErroUsuario('Papel inválido.');
458	  if (id === req.usuario.id) throw new ErroUsuario('Você não pode mudar o seu próprio papel.');
459	  db.prepare('UPDATE usuarios SET papel = ? WHERE id = ?').run(papel, id);
460	  res.redirect('/admin');
461	});
462	
