12	  EXISTS (SELECT 1 FROM curtidas c WHERE c.post_id = p.id AND c.usuario_id = ?) AS curti
13	FROM posts p JOIN usuarios u ON u.id = p.usuario_id`;
14	
15	// Em caso de empate no horário, a conquista aparece acima do post que a gerou.
16	const SQL_ITENS = `
17	SELECT tipo, id FROM (
18	  SELECT 'post' AS tipo, id, criado_em, 2 AS ordem FROM posts
19	  UNION ALL
20	  SELECT 'medalha', id, criado_em, 1 FROM medalhas
21	  UNION ALL
22	  SELECT 'conquista', ca.id, ca.criado_em, 0 FROM conquistas_alunos ca
23	    JOIN usuarios u ON u.id = ca.aluno_id
24	    WHERE ca.anunciar = 1 AND u.papel = 'aluno'
25	)
26	ORDER BY criado_em DESC, ordem, id DESC
27	LIMIT ? OFFSET ?`;
28	
29	const porId = (linhas) => new Map(linhas.map((l) => [l.id, l]));
30	const lista = (ids) => JSON.stringify(ids);
31	
32	function carregarPosts(ids, usuarioId) {
33	  if (ids.length === 0) return new Map();
34	  const posts = db.prepare(`${SQL_POST} WHERE p.id IN (SELECT value FROM json_each(?))`).all(usuarioId, lista(ids));
35	  // Últimos comentários de cada post, numa consulta só.
36	  const comentarios = db
37	    .prepare(
38	      `SELECT * FROM (
39	         SELECT c.*, u.nome, u.papel, ROW_NUMBER() OVER (PARTITION BY c.post_id ORDER BY c.id DESC) AS n
40	         FROM comentarios c JOIN usuarios u ON u.id = c.usuario_id
41	         WHERE c.post_id IN (SELECT value FROM json_each(?))
42	       ) WHERE n <= ? ORDER BY id`,
43	    )
44	    .all(lista(ids), COMENTARIOS_NO_FEED);
45	  for (const p of posts) p.ultimos_comentarios = comentarios.filter((c) => c.post_id === p.id);
46	  return porId(posts);
47	}
48	
49	function carregarMedalhas(ids) {
50	  if (ids.length === 0) return new Map();
51	  return porId(
52	    db
53	      .prepare(
54	        `SELECT m.id, m.mensagem, m.criado_em, m.aluno_id AS usuario_id, a.nome, a.avatar, a.papel, a.curso,
55	           t.nome AS medalha, t.emoji, t.pontos, m.professor_id, pr.nome AS professor_nome
56	         FROM medalhas m JOIN usuarios a ON a.id = m.aluno_id JOIN tipos_medalha t ON t.id = m.tipo_id
57	         LEFT JOIN usuarios pr ON pr.id = m.professor_id
58	         WHERE m.id IN (SELECT value FROM json_each(?))`,
59	      )
60	      .all(lista(ids)),
61	  );
62	}
63	
64	function carregarConquistas(ids) {
65	  if (ids.length === 0) return new Map();
66	  const linhas = db
67	    .prepare(
68	      `SELECT ca.id, ca.conquista, ca.criado_em, ca.aluno_id AS usuario_id, u.nome, u.avatar, u.papel, u.curso
69	       FROM conquistas_alunos ca JOIN usuarios u ON u.id = ca.aluno_id
70	       WHERE ca.id IN (SELECT value FROM json_each(?))`,
71	    )
72	    .all(lista(ids));
73	  // Junta com os dados da conquista (emoji, nome, bônus). Conquistas que saíram das regras somem.
74	  return porId(linhas.map((l) => ({ ...l, info: CONQUISTAS.find((c) => c.id === l.conquista) })).filter((l) => l.info));
75	}
76	
77	// Retorna { itens, temMais }. Cada item é { tipo: 'post' | 'medalha' | 'conquista', dados }.
78	function pagina({ usuarioId, pagina, porPagina }) {
79	  const linhas = db.prepare(SQL_ITENS).all(porPagina + 1, (pagina - 1) * porPagina);
80	  const temMais = linhas.length > porPagina;
81	  const itens = linhas.slice(0, porPagina);
82	  const ids = (tipo) => itens.filter((i) => i.tipo === tipo).map((i) => i.id);
83	  const dados = {
84	    post: carregarPosts(ids('post'), usuarioId),
85	    medalha: carregarMedalhas(ids('medalha')),
86	    conquista: carregarConquistas(ids('conquista')),
87	  };
88	  return {
89	    itens: itens.map((i) => ({ tipo: i.tipo, dados: dados[i.tipo].get(i.id) })).filter((i) => i.dados),
90	    temMais,
91	  };
92	}
93	
94	module.exports = { SQL_POST, pagina };
