  <a class="btn btn-sec btn-largo" href="/u/${id}/trofeus">🏆 ${
    faltam ? `Ver troféus e ${proprio ? 'próximas conquistas' : 'conquistas que faltam'} (${faltam})` : 'Ver todos os troféus'
  }</a>
</section>`;
}

